// Search research – build the Neo4j vector query. Mode: Run Once for All Items.
const embedding = $input.first().json.embeddings?.[0];
if (!embedding) throw new Error('Ollama returned no embedding – is nomic-embed-text pulled and Ollama running?');

const statement = `
CALL db.index.vector.queryNodes('chunk_embedding', $k, $embedding) YIELD node, score
MATCH (p:Paper)-[:HAS_CHUNK]->(node)
RETURN p.id AS paperId, p.title AS title, p.authors AS authors, p.year AS year, p.url AS url,
       p.position AS paperPosition, round(score, 3) AS score, node.text AS text
ORDER BY score DESC`;

return [{ json: { body: { statement, parameters: { k: 6, embedding }, accessMode: 'Read' } } }];

// Search research – turn Neo4j's response into readable passages with citations. Mode: Run Once for All Items.
const res = $input.first().json;
if (res.errors?.length) throw new Error(`Neo4j error: ${res.errors[0].code} – ${res.errors[0].message}`);
const { fields, values } = res.data;
const rows = values.map(v => Object.fromEntries(fields.map((f, i) => [f, v[i]])));
if (!rows.length) return [{ json: { response: 'No matching passages found in the research papers.' } }];

const cite = r => `${r.authors[0].split(' ').pop()}${r.authors.length > 1 ? ' et al.' : ''} (${r.year})`;
const passages = rows.map((r, i) =>
  `[${i + 1}] ${cite(r)}, "${r.title}" – similarity ${r.score}\n${r.text}`).join('\n\n');
const papers = [...new Map(rows.map(r => [r.paperId, r])).values()]
  .map(r => `- ${cite(r)}: ${r.paperPosition} <${r.url}>`).join('\n');

return [{ json: { response: `PASSAGES\n\n${passages}\n\nPAPERS (one-line summaries written for this project)\n${papers}` } }];
